  "Maç devam ediyor...": "Partido en curso...",
  "Maç, turnuva ve lig sıralama ödülleri": "Premios de partidos, torneos y clasificación de liga",
  "Maç, lig ve turnuva ödülleri otomatik olarak": "Los premios de partidos, ligas y torneos se añaden automáticamente",
  "ödenir. Ödeme günleri: sezonun": "se abona. Días de pago de la temporada:",
  "Antrenman, seçtiğin yeteneğe": "Al entrenar, la habilidad que elijas recibe",
  "kazandırır; yetenek seviyen yükseldikçe oyuncu gücün (OVR) artar.": "y, a medida que sube su nivel, aumenta tu valoración general (OVR).",
  ". İstediğin gruptan çalışabilirsin.": ". Puedes entrenar en el grupo que quieras.",
  ". Farklı gruba (Kaleci / Defans / Orta Saha / Forvet) geçişte": ". Cambiar a otro grupo (Portero / Defensa / Centrocampista / Delantero) cuesta",
  "ve o grubun yeni yetenekleri 10'dan başlar.": "y los nuevos atributos de ese grupo empiezan en 10.",
  "eşittir (Sv.1 → 1 eş zamanlı).": "equivale (Nv.1 → 1 simultáneo).",
  "ile başlarsın. Takım tesisin (Performans Merkezi) her seviye için": "para empezar. Tu instalación del equipo (Centro de Rendimiento) añade por cada nivel",
  "harcama; hangisi önce dolarsa orada durur.": "de gasto; lo que se alcance antes marca el tope.",
  "işlenir, her bilet denetim için kaydedilir.": "y cada boleto queda registrado para auditoría.",
  "kazanır. Elmas ortalama her 200 bilette bir çıkar.": "gana. De media sale un diamante cada 200 boletos.",
  "'de sıfırlanır. Kazanç tavanı Toto ile ortaktır.": ". El límite de ganancias se comparte con Toto.",
  "Ücretsiz günlük bilet 25'e sayılmaz. Tüm sayaçlar": "El boleto diario gratis no cuenta para los 25. Todos los contadores se reinician a las",
  "güncel sezon maaşı ÷ 4": "salario de temporada actual ÷ 4",
  "ve talep ettiğin": "y la cantidad que pides de",
  "(final galibi) ayrıca": "(ganador de la final) suma además",
  "de buluşur. Final hariç tüm turlar çift maçlıdır.": "se enfrentan. Todas las rondas, salvo la final, se juegan a ida y vuelta.",
  ". Lig sonunda hak kazanan takımlar turnuvalara katılır.": ". Los equipos que se clasifiquen al final de la liga entran en los torneos.",
  "olarak katılacaksın. İstediğin zaman ayrılabilirsin.": "será tu rol al unirte. Puedes salir cuando quieras.",
  ". Diğer üyeler oylarını veriyor.": ". Los demás miembros están votando.",
  ". Sonraki seçimde tekrar başvurabilirsin.": ". Puedes volver a presentarte en las próximas elecciones.",
  "Karşı takım kaptanı kabul ederse maç planlanır.": "El partido se programa si el capitán rival acepta.",
  "(Sahadan çıkarmak için diziliş ekranında yedeğe sürükleyin.)": "(Para sacar a un jugador, arrástralo a los suplentes en la pantalla de alineación.)",
  ". Tüm takımlar, oyuncular ve maçlar kurgusaldır.": ". Todos los equipos, jugadores y partidos son ficticios.",
  ". Katılım yalnızca oyun içi sanal para ile yapılır;": ". La participación es solo con moneda virtual del juego;",
  ", kazanılan ödüller yalnızca oyun içinde kullanılır ve": ", los premios obtenidos solo se usan dentro del juego y",
  ", oyuncunun yeteneklerinin ortalamasıdır ve": ", es la media de los atributos del jugador y",
