  "belirlenir: oyuncunun güncel yetenek seviyesine göre hesaplanır, oyuncu geliştikçe maaşı artar. Her maaş gününde": "se fija automáticamente: se calcula según el nivel de habilidad actual del jugador, así que el salario sube a medida que mejora. En cada día de pago",
