  "Düzenli antrenman, takımdaki yerini ve transfer değerini yükseltmenin en hızlı yoludur.": "Entrenar con regularidad es la forma más rápida de ganar sitio en la plantilla y subir tu valor de traspaso.",
  "Enerji sunucu saatiyle (UTC 00:00) yenilenir. Bu, her ülkede aşağıdaki yerel saate denk gelir:": "La energía se recarga según la hora del servidor (UTC 00:00). Eso equivale a la siguiente hora local en cada país:",
