  "💡 Diamond ile oyuncu transfer eder, tesis yükseltir, item ve takım satın alabilirsin. Büyük paketler kademeli bonus kazandırır.": "💡 Con diamantes puedes fichar jugadores, mejorar instalaciones y comprar objetos o equipos. Los packs más grandes dan bonus cada vez mayores.",
