  "Yüksek seviyeli antrenmanlar daha çok enerji harcar — verimli puan demek.": "Los entrenamientos de mayor nivel gastan más energía — es decir, puntos más eficientes.",
  "Kadronu kontrol et, akıllı kadro öner butonuyla en iyi 11'i hızlıca diz!": "Revisa tu plantilla — ¡usa el botón de plantilla inteligente para alinear rápido el mejor once!",
  "Sahadaki oyuncuya dokun → yedeklerden birini seç. Sürüklemek için karta": "Toca un jugador en el campo → elige uno de los suplentes. Para arrastrar, en la tarjeta",
  "seçildi → sahadan değişecek oyuncuyu seç.": "seleccionado → elige al jugador que sale.",
  "Hazırlıklarını yap. Strateji ve kadro ayarlarını gözden geçir.": "Prepárate. Revisa tu estrategia y los ajustes de la plantilla.",
  "Bir sonraki sezon hazırlıkları için kadronu yeniden şekillendirme zamanı.": "Es hora de remodelar tu plantilla para la próxima temporada.",
  "kadronu güçlendirmek, sakat veya formdan düşen oyuncularını değiştirmek için": "para reforzar tu plantilla y sustituir a jugadores lesionados o en baja forma",
  "• Bitkin oyuncular maçta düşük performans gösterir ve sakatlanma riski artar.": "• Los jugadores agotados rinden mal en el partido y tienen más riesgo de lesionarse.",
  "• Kullanılmayan enerji birikmez, gün sonunda sıfırlanır.": "• La energía no usada no se acumula; se reinicia al final del día.",
  "• Antrenmana devam ederek daha da yükselebilirsin.": "• Sigue entrenando para subir todavía más.",
