  "Bir hafta boyunca oynadığın tüm maçların reytinglerinin": "De las valoraciones de todos los partidos que juegas durante una semana,",
  "alan oyuncular yarışır. Maç motoru her maçta oyuncularının performansını 17 farklı kategoride değerlendirir ve bir maç sonu reytingi üretir.": "jugadores compiten. El motor de partidos evalúa el rendimiento de cada jugador en 17 categorías y genera una valoración final del partido.",
  "oyuncular yarışır. Antrenman seansı yaptığında harcadığın enerji bu yarışın puanına eklenir.": "jugadores compiten. La energía que gastas en las sesiones de entrenamiento suma puntos en esta carrera.",
  "Ödülünü ödül penceresi içinde toplamazsan iptal olur. Yeni yarış başladıktan sonra eski ödüller kaybolur.": "Si no reclamas tu recompensa dentro del plazo de recompensa, se cancela. Las recompensas antiguas se pierden cuando empieza una nueva carrera.",
  "✅ Bu serideki tüm hediyelerini topladın. Yarın da gir, seri devam etsin!": "✅ Has recogido todos los regalos de esta racha. ¡Entra también mañana para mantenerla!",
  "🚪 Her gün giriş yap, serini büyüt! İlk gün hediyesi seni bekliyor.": "🚪 ¡Entra cada día y aumenta tu racha! Te espera el regalo del primer día.",
  "toplanmamış hediyen var! Toplamadan gün kaçırırsan yanar.": "¡regalos sin recoger! Si pasas un día sin recogerlos, caducan.",
  "Bir takıma katılıp maç oynadığında buraya yansıyacak.": "Se reflejará aquí cuando te unas a un equipo y juegues partidos.",
  "Takım Puanı her resmi maç sonucunun kademe çarpanıyla hesaplanır (Takımlar sekmesindeki bilgi kutusuyla aynı çarpanlar).": "Los Puntos de equipo se calculan a partir de cada resultado oficial con el multiplicador de categoría (los mismos multiplicadores que el cuadro informativo de la pestaña Equipos).",
  "maç sonucu, oynanan kademenin çarpanıyla puana çevrilip toplanır. Hazırlık ve milli maçlar sayılmaz.": "los resultados se convierten en puntos con el multiplicador de la categoría jugada y se suman. No cuentan los amistosos ni los partidos internacionales.",
  "takımlar arasında gerçek küresel sıradır.": "es la verdadera clasificación global entre equipos.",
  "katkısı sayılır; 6. sezon başlayınca en eski sezon düşer. Her sezonun katkısı satırdaki kartlarda ayrı görünür.": "cuentan; al empezar la temporada 6 se descarta la más antigua. La aportación de cada temporada se muestra por separado en las tarjetas de la fila.",
