  "💡 Şartları karşılayan oyuncular onaysız direkt katılır. Karşılamayanlar onay isteğini gönderir, sen veya yardımcı kaptanlar onaylar.": "💡 Los jugadores que cumplen los requisitos se unen directamente sin aprobación. Los que no, envían una solicitud para que la apruebes tú o un vicecapitán.",
  "gün ileri tarihe hazırlık maçı ayarlayabilirsin.": "días de margen puedes programar un amistoso.",
