  "). Günde en fazla 1 hazırlık maçı yapılabilir.": "). Se permite como máximo 1 amistoso al día.",
  "). Tesisleri yükselt veya bir oyuncu kov.": "). Mejora las instalaciones o despide a un jugador.",
  "). 32 milli takım 8 gruba ayrılacak. Eşleşmeler kura sonrası burada görünecek.": "). Las 32 selecciones nacionales se repartirán en 8 grupos. Los cruces aparecerán aquí tras el sorteo.",
  "'de takvimimiz uygun değil. Başka bir zaman tekrar deneyebilirsin.": "no nos viene bien por calendario. Puedes volver a intentarlo en otro momento.",
  "'deki hazırlık maçı teklifini kabul ediyoruz. Hazırız!": "aceptamos tu oferta de amistoso. ¡Estamos listos!",
  "Davet için teşekkürler ama o tarihte hazırlık programımız dolu. Bir dahaki sefere.": "Gracias por la invitación, pero ese día tenemos la agenda de pretemporada completa. Será la próxima vez.",
  "olarak şu an hazırlık maçı için müsait değiliz.": "ahora mismo no estamos disponibles para un amistoso.",
  ": Çeviri yakında! Şimdilik Türkçe kullanılıyor.": ": ¡Traducción próximamente! Por ahora se usa el turco.",
  "Backend bağlandığında dünya üzerindeki kullanıcıların paylaşımları burada gözükecek.": "Cuando se conecte el backend, aquí aparecerán las publicaciones de usuarios de todo el mundo.",
  "Backend bağlandığında takip ettiğin kullanıcıların paylaşımları burada gözükecek.": "Cuando se conecte el backend, aquí aparecerán las publicaciones de los usuarios que sigues.",
  "Backend bağlandığında ülkendeki kullanıcıların paylaşımları burada gözükecek.": "Cuando se conecte el backend, aquí aparecerán las publicaciones de usuarios de tu país.",
