  "Maçları simüle etmek, lig ve turnuvaları yürütmek": "Simular partidos y gestionar ligas y torneos",
  "Konum, kişi listesi, kamera, mikrofon veya reklam kimliği": "Ubicación, contactos, cámara, micrófono o ID de publicidad",
  "e-posta adresi, kullanıcı adı, oyuncu adı, uyruk ve yaş aralığı.": "correo electrónico, nombre de usuario, nombre del jugador, nacionalidad y rango de edad.",
  "e-posta adresin, cüzdan hareketlerin, gelen kutun, ekipmandan gelen bonus ayrıntıların.": "tu correo electrónico, los movimientos de tu cartera, tu bandeja de entrada y los detalles de bonus del equipamiento.",
  "oyuncu adın, takımın, yetenek toplamların, maç istatistiklerin, paylaşımların.": "tu nombre de jugador, tu equipo, tus totales de habilidades, tus estadísticas de partidos y tus publicaciones.",
  "takım sohbeti, CSC Media paylaşımları, gelen kutusu mesajları, federasyon oyları.": "chat del equipo, publicaciones de CSC Media, mensajes de la bandeja de entrada y votos de la federación.",
  "takım, kadro, yetenek seviyeleri, maç istatistikleri, kupalar, cüzdan bakiyesi (oyun içi € ve 💎), kuponlar, envanter.": "equipo, plantilla, niveles de habilidad, estadísticas de partidos, trofeos, saldo de la cartera (€ y 💎 del juego), boletos e inventario.",
  "Veriler Supabase (PostgreSQL) altyapısında, şifreli bağlantı üzerinden saklanır. Şifreler tek yönlü olarak saklanır; hiç kimse ham şifreni göremez.": "Los datos se almacenan en Supabase (PostgreSQL) mediante una conexión cifrada. Las contraseñas se guardan de forma irreversible; nadie puede ver tu contraseña original.",
  "Hesabın aktif olduğu sürece. Hesabını sildiğinde kişisel verilerin kalıcı olarak kaldırılır (bkz. madde 7).": "Mientras tu cuenta esté activa. Si eliminas tu cuenta, tus datos personales se borran de forma permanente (ver apartado 7).",
  "hangi verilerin tutulduğunu talep edebilirsin.": "puedes solicitar información sobre qué datos se guardan.",
  "İstediğin zaman Ayarlar → Hesabımı Sil ile hesabını kalıcı olarak silebilirsin.": "Puedes eliminar tu cuenta de forma permanente en cualquier momento en Ajustes → Eliminar mi cuenta.",
  "Ayarlar → Hesabımı Sil ile tüm verini kalıcı silebilirsin.": "Puedes borrar todos tus datos de forma permanente en Ajustes → Eliminar mi cuenta.",
  "profil bilgilerini uygulama içinden değiştirebilirsin.": "puedes cambiar los datos de tu perfil desde la app.",
  "Oyun 13 yaşın altındaki kullanıcılara yönelik değildir. Bilerek 13 yaş altından veri toplamayız.": "El juego no está dirigido a menores de 13 años. No recopilamos a sabiendas datos de menores de 13 años.",
  "Başkasının hesabını kullanmak veya hesap alışverişi yasaktır.": "Está prohibido usar la cuenta de otra persona o comerciar con cuentas.",
  "Hile, otomasyon (bot), açık kötüye kullanımı yasaktır.": "Están prohibidos las trampas, la automatización (bots) y el aprovechamiento de fallos.",
  "Hakaret, taciz, nefret söylemi ve spam yasaktır.": "Están prohibidos los insultos, el acoso, el discurso de odio y el spam.",
  "Kural ihlalinde hesap askıya alınabilir veya kapatılabilir.": "Incumplir las normas puede suponer la suspensión o el cierre de la cuenta.",
  "Paylaştığın metinlerden sen sorumlusun. Kurallara aykırı içerik uyarı yapılmadan kaldırılabilir.": "Eres responsable de los textos que publicas. El contenido que incumpla las normas puede eliminarse sin previo aviso.",
  "Oyun geliştirme aşamasındadır. Özellikler değişebilir, denge ayarları yapılabilir; bakım nedeniyle geçici kesintiler olabilir.": "El juego está en desarrollo. Las funciones pueden cambiar, el equilibrio puede ajustarse y puede haber interrupciones temporales por mantenimiento.",
  "Oyun \"olduğu gibi\" sunulur. Veri kaybı veya kesintilerden doğan dolaylı zararlardan sorumluluk kabul edilmez.": "El juego se ofrece \"tal cual\". No se acepta responsabilidad por daños indirectos derivados de pérdidas de datos o interrupciones.",
  "yalnızca oyun içinde geçerli sanal değerlerdir. Gerçek para karşılığı değildir, nakde çevrilemez, oyun dışına aktarılamaz ve gerçek bir değer taşımaz.": "son valores virtuales válidos solo dentro del juego. No son dinero real, no se pueden canjear por dinero ni transferir fuera del juego y no tienen valor real.",
  "Sorular için Ayarlar → Talep İlet üzerinden yöneticiye ulaşabilirsin.": "Si tienes preguntas, puedes contactar con el administrador en Ajustes → Enviar solicitud.",
